/** GhostDeck integration: Kiro-generated engine/scenarios, reviewed and integrated with Codex. */
import {validateDeck,createInitialSession,applyChoice,toggleEvidence,resetSession,exportSessionReport,exportDeckJson,importDeckJson,MAX_SESSION_LENGTH,MAX_IMPORT_BYTES} from './engine.js';
import {saveSession,loadSession,clearAllData} from './storage.js';
const $=id=>document.getElementById(id);
const node=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;};
const clone=value=>JSON.parse(JSON.stringify(value));
let session=null,mode='play',draft=null,editingId=null,restoreFocus=null,loading=false;
const seeds=[{id:'release-rollback',name:'The midnight release',subtitle:'A deployment goes wrong. Roll back now, or investigate first?',time:'5–8 MIN',label:'01 / SOFTWARE TEAM'},{id:'lost-badge',name:'The missing badge',subtitle:'Someone needs access. The evidence is incomplete. What comes next?',time:'4–6 MIN',label:'02 / WORKPLACE TEAM'}];
function status(message){$('status').textContent=message;}
function persist(){const r=saveSession(session);if(!r.success)status('This session is working in memory. Browser storage is unavailable; export your stack or debrief to keep a copy.');}
function install(deck,id){session=createInitialSession(deck,id);draft=null;mode='play';$('library').hidden=true;$('studio').hidden=false;persist();render();}
async function loadSeed(id){if(loading)return;loading=true;status('Opening card stack…');try{const r=await fetch(new URL('../data/'+id+'.json',import.meta.url));if(!r.ok)throw Error('Scenario file unavailable');const v=validateDeck(await r.json());if(!v.valid)throw Error(v.errors.join('; '));install(v.deckObj,id);status('Fictional rehearsal ready. Take your time.');$('card-title').focus();}catch(e){status(e.message);}finally{loading=false;}}
function download(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=node('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);status('Exported '+name+'. Keep it somewhere you trust.');}
function changeMode(next){if(!session)return;mode=next;if(mode==='author'){draft=exportDeckJson(session.deck);editingId=session.currentCardId;renderAuthor();}render();}
function choose(index){if(!session||mode!=='play'||$('import-dialog').open)return;const c=session.deck.cards.get(session.currentCardId);const choice=c.choices[index];if(!choice)return;const next=applyChoice(session,choice.destination,index);if(next===session){status('This path has ended or reached the 200-decision limit. Open the debrief or restart.');return;}session=next;persist();render();$('card-title').focus();status('Decision '+session.history.length+' recorded.');}
function render(){if(!session)return;$('deck-title').textContent=session.deck.title;$('deck-description').textContent=session.deck.description;$('session-count').textContent=session.history.length+' DECISIONS / '+MAX_SESSION_LENGTH+' MAX';for(const name of ['play','author','replay']){$('mode-'+name).setAttribute('aria-pressed',String(mode===name));$(name+'-panel').hidden=mode!==name;}$('map-hint').textContent=mode==='author'?'Select any card to edit its content and links.':'Visited cards light up as your path emerges.';renderMap();if(mode==='play')renderPlay();if(mode==='replay')renderReplay();}
function renderMap(){const map=$('card-map');map.replaceChildren();const visited=new Set(session.history.map(r=>r.cardId));visited.add(session.currentCardId);const cards=mode==='author'?draft.cards:[...session.deck.cards.values()];cards.forEach((card,index)=>{const b=node('button',undefined,'map-card');const current=mode==='author'?editingId===card.id:session.currentCardId===card.id;b.classList.toggle('current',current);b.classList.toggle('visited',visited.has(card.id));b.append(node('small',String(index+1).padStart(2,'0')+' / '+(card.isTerminal?'ENDING':'CARD')),node('span',mode==='author'||visited.has(card.id)?card.title:'Unexplored card'));b.setAttribute('aria-current',current?'step':'false');b.disabled=mode!=='author';if(mode==='author')b.addEventListener('click',()=>{try{collectDraft();editingId=card.id;renderAuthor();renderMap();}catch(e){$('author-errors').textContent=e.message;}});map.append(b);});}
function evidenceRows(parent,evidence){parent.replaceChildren();for(const item of evidence){const r=node('div',undefined,'evidence-row');r.append(node('strong',item.label),node('p',item.content));parent.append(r);}}
function renderPlay(){const card=session.deck.cards.get(session.currentCardId);$('card-title').textContent=card.title;$('card-narrative').textContent=card.narrative;const index=[...session.deck.cards.keys()].indexOf(card.id)+1;$('card-number').textContent='CARD '+String(index).padStart(2,'0')+' / '+session.deck.cards.size;$('card-status').textContent=card.isTerminal?'END OF PATH':'YOUR NEXT MOVE';const revealed=session.evidenceRevealed.has(card.id);$('evidence-toggle').disabled=card.evidence.length===0;$('evidence-toggle').textContent=(revealed?'Hide':'Reveal')+' evidence ('+card.evidence.length+')';$('evidence-toggle').setAttribute('aria-expanded',String(revealed));$('evidence').hidden=!revealed;evidenceRows($('evidence'),card.evidence);$('choices').replaceChildren();const done=card.isTerminal||session.history.length>=MAX_SESSION_LENGTH;$('terminal').hidden=!done;if(!done)card.choices.forEach((c,i)=>{const b=node('button',undefined,'decision-choice');b.append(node('span',String(i+1),'key'),node('span',c.label),node('span','→','arrow'));b.addEventListener('click',()=>choose(i));$('choices').append(b);});}
function renderReplay(){const report=exportSessionReport(session);$('replay-summary').textContent=report.steps+' decisions · '+session.evidenceRevealed.size+' evidence panels currently open · '+(report.finalStatus==='terminal'?'An authored ending was reached.':'This rehearsal is still in progress.');const parent=$('replay-steps');parent.replaceChildren();if(!session.history.length)parent.append(node('p','No choices yet. Begin the rehearsal, then come back to reflect.'));session.history.forEach((r,i)=>{const item=node('article',undefined,'replay-step');item.append(node('p','DECISION '+String(i+1).padStart(2,'0'),'step-label'),node('h3',r.cardTitle||r.cardId),node('p','You chose: '+r.choiceLabel),node('p','Next: '+session.deck.cards.get(r.destinationId).title),node('p',r.evidenceWasRevealed?'Evidence was open when you decided.':'Evidence was not open when you decided.'));const details=node('details');details.append(node('summary',r.evidenceSnapshot.length+' evidence items were available at this point'));const rows=node('div');evidenceRows(rows,r.evidenceSnapshot);details.append(rows);item.append(details);parent.append(item);});$('export-report').disabled=!session.history.length;}
function field(label,value,kind='input'){const l=node('label',label);const input=node(kind);input.value=value;l.append(input);return {label:l,input};}
function editableEvidence(value){const row=node('div',undefined,'editor-row');const label=field('Label',value.label);label.input.maxLength=200;label.input.dataset.field='label';const content=field('Evidence text',value.content,'textarea');content.input.rows=2;content.input.maxLength=5000;content.input.dataset.field='content';const remove=node('button','×','remove');remove.type='button';remove.setAttribute('aria-label','Remove evidence item');remove.onclick=()=>row.remove();row.append(label.label,content.label,remove);return row;}
function editableChoice(value){const row=node('div',undefined,'editor-row');const label=field('Choice text',value.label);label.input.maxLength=200;label.input.dataset.field='label';const destination=field('Destination','','select');destination.input.dataset.field='destination';for(const c of draft.cards){const option=node('option',c.title+' ['+c.id+']');option.value=c.id;destination.input.append(option);}destination.input.value=value.destination;const remove=node('button','×','remove');remove.type='button';remove.setAttribute('aria-label','Remove choice');remove.onclick=()=>row.remove();row.append(label.label,destination.label,remove);return row;}
function renderAuthor(){const card=draft.cards.find(c=>c.id===editingId);$('author-title').value=card.title;$('author-narrative').value=card.narrative;$('author-terminal').checked=card.isTerminal;$('author-evidence').replaceChildren(...card.evidence.map(editableEvidence));$('author-choices').replaceChildren(...card.choices.map(editableChoice));$('author-errors').textContent='';$('draft-preview').hidden=true;}
function collectDraft(){const card=draft.cards.find(c=>c.id===editingId);card.title=$('author-title').value;card.narrative=$('author-narrative').value;card.isTerminal=$('author-terminal').checked;card.evidence=[...$('author-evidence').children].map(r=>({label:r.querySelector('[data-field="label"]').value,content:r.querySelector('[data-field="content"]').value}));card.choices=[...$('author-choices').children].map(r=>({label:r.querySelector('[data-field="label"]').value,destination:r.querySelector('[data-field="destination"]').value}));return card;}
function openImport(){restoreFocus=document.activeElement;$('import-errors').textContent='';$('import-json').value='';$('import-file').value='';$('import-dialog').showModal();$('import-json').focus();}
$('import-dialog').addEventListener('close',()=>restoreFocus?.focus());
$('import-file').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;if(f.size>MAX_IMPORT_BYTES){$('import-errors').textContent='Import exceeds the 1 MiB size limit.';return;}try{$('import-json').value=await f.text();$('import-errors').textContent='File loaded. Validate to open it.';}catch{$('import-errors').textContent='Could not read this file.';}});
$('confirm-import').onclick=()=>{const result=importDeckJson($('import-json').value);if(!result.success){$('import-errors').textContent=result.errors.join('\n');return;}install(result.deckObj,'imported');$('import-dialog').close();$('card-title').focus();status('Imported and validated. A fresh rehearsal is ready.');};
$('author-form').onsubmit=e=>{e.preventDefault();try{collectDraft();const v=validateDeck(draft);if(!v.valid){$('author-errors').textContent=v.errors.join('\n');return;}const id=session.deckId;install(v.deckObj,id);status('Stack validated and applied. A fresh rehearsal keeps your old decisions separate from your new content.');$('card-title').focus();}catch(error){$('author-errors').textContent=error.message;}};
$('preview-card').onclick=()=>{const card=collectDraft();const p=$('draft-preview');p.replaceChildren(node('p','DRAFT PREVIEW / NOT APPLIED','eyebrow'),node('h2',card.title),node('p',card.narrative));p.hidden=false;};
$('discard-draft').onclick=()=>{mode='play';draft=null;render();status('Draft discarded. Your active rehearsal is unchanged.');};
$('add-evidence').onclick=()=>{if($('author-evidence').children.length<20)$('author-evidence').append(editableEvidence({label:'New evidence',content:'Describe the information available here.'}));};
$('add-choice').onclick=()=>{if($('author-choices').children.length<10)$('author-choices').append(editableChoice({label:'A different next step',destination:draft.cards.find(c=>c.id!==editingId)?.id||editingId}));};
$('evidence-toggle').onclick=()=>{session=toggleEvidence(session,session.currentCardId);persist();renderPlay();};
$('restart').onclick=()=>{session=resetSession(session);mode='play';draft=null;persist();render();status('A clean rehearsal. Your stack edits are preserved.');};
$('home').onclick=()=>{$('library').hidden=false;$('studio').hidden=true;status('Your last rehearsal stays saved in this browser. Opening another stack starts a new one.');};
$('clear-storage').onclick=()=>{const r=clearAllData();status(r.success?'Saved rehearsal cleared. The open session stays in memory until you leave.':r.error);};
$('quickstart').onclick=()=>loadSeed('release-rollback');
$('import-library').onclick=openImport;$('import-studio').onclick=openImport;
$('export-deck').onclick=()=>download(exportDeckJson(session.deck),'ghostdeck-stack.json');
$('export-report').onclick=()=>download({...exportSessionReport(session),format:'ghostdeck-debrief-v1',fictional:true},'ghostdeck-debrief.json');
for(const n of ['play','author','replay'])$('mode-'+n).onclick=()=>changeMode(n);
$('open-debrief').onclick=()=>changeMode('replay');
document.addEventListener('keydown',e=>{if(e.altKey||e.ctrlKey||e.metaKey||e.repeat||['INPUT','TEXTAREA','SELECT','BUTTON','SUMMARY'].includes(e.target.tagName)||e.target.isContentEditable)return;if(/^[1-9]$/.test(e.key)&&!$('studio').hidden){e.preventDefault();choose(Number(e.key)-1);}});
for(const seed of seeds){const tile=node('article',undefined,'scenario-tile');tile.append(node('span',seed.label,'tile-num'),node('h3',seed.name),node('p',seed.subtitle));const bottom=node('div',undefined,'tile-bottom');const b=node('button','Open stack →','quiet');b.onclick=()=>loadSeed(seed.id);b.setAttribute('aria-label','Open '+seed.name);bottom.append(node('span',seed.time+' · FICTIONAL'),b);tile.append(bottom);$('scenarios').append(tile);}
const saved=loadSession();if(saved.success){session=saved.session;$('library').hidden=true;$('studio').hidden=false;render();status('Your last rehearsal has been restored from this browser.');}else if(saved.error){status('Saved data could not be restored. Start a fresh rehearsal or import a stack.');}
